import { ChangeDetectionStrategy, Component, Inject, OnInit, PLATFORM_ID } from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../core/services/translation.service';

@Component({
  selector: 'app-terms-and-conditions',
  standalone: true,
  imports: [TranslateModule],
  templateUrl: './terms-and-conditions.component.html',
  styleUrl: './terms-and-conditions.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TermsAndConditionsComponent implements OnInit {
  constructor(@Inject(DOCUMENT) private document: Document, @Inject(PLATFORM_ID) private platformId: Object,  public translationService: TranslationService,) { }

  ngOnInit(): void {
    if (!isPlatformBrowser(this.platformId)) return;
    setTimeout(() => {
      window.scroll({
        top: 0,
        left: 0,
        behavior: 'smooth'
      });
    }, 500);
    this.addSchema();
    this.addBreadcrumbSchema();
  }

  addSchema() {
    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "terms-and-conditions-webpage-schema";
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "WebPage",
      "name": "Terms and Conditions",
      "description": "Read the terms and conditions for using our services.",
      "url": "https://www.pixtar.ae/terms-and-conditions"
    });

    this.document.head.appendChild(script);
  }

  private addBreadcrumbSchema(): void {
    const existingScript = this.document.getElementById("breadcrumb-schema-terms-and-conditions");
    if (existingScript) {
      return;
    }

    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "breadcrumb-schema-terms-and-conditions";

    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Home",
          "item": "https://www.pixtar.ae/"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "Terms and Conditions",
          "item": "https://www.pixtar.ae/terms-and-conditions"
        }
      ]
    });

    this.document.head.appendChild(script);
  }
}
